def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    foreground = next((value for value in counts if value != background), background)
    out = [row[:] for row in grid]

    def isolated(r, c):
        return all(
            not (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == foreground)
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1))
        )

    for axis in (0, 1):
        line_count = h if axis == 0 else w
        line_length = w if axis == 0 else h
        for k in range(line_count):
            positions = [t for t in range(line_length)
                         if (grid[k][t] if axis == 0 else grid[t][k]) == foreground]
            # Complete dense or multi-cell line patterns, and short isolated pairs.
            runs = []
            for t in positions:
                if not runs or t > runs[-1][-1] + 1:
                    runs.append([t])
                else:
                    runs[-1].append(t)
            qualifies = len(positions) >= 4 or sum(len(run) >= 2 for run in runs) >= 2
