                    qualifies = isolated(k, positions[0]) and isolated(k, positions[1])
                else:
                    qualifies = isolated(positions[0], k) and isolated(positions[1], k)
            if qualifies:
                for left, right in zip(positions, positions[1:]):
                    for t in range(left + 1, right):
                        if axis == 0:
                            out[k][t] = 2
                        else:
                            out[t][k] = 2
    return out
